export type ClauseCategory =
  | 'introduction'
  | 'scope'
  | 'context'
  | 'leadership'
  | 'planning'
  | 'support'
  | 'operation'
  | 'performance'
  | 'improvement';

export type ClauseNode = {
  code: string;
  title: string;
  summary: string;
  parentCode: string | null;
  level: number;
  category: ClauseCategory;
  owner: string;
  auditWeight: number;
  csrRelevant: boolean;
  recommendedDocuments: string[];
  keywords: string[];
  requiresDocument: boolean;
};

type ClauseInput = [
  code: string,
  title: string,
  summary: string,
  parentCode: string | null,
  category: ClauseCategory,
  owner: string,
  auditWeight: number,
  csrRelevant: boolean,
  recommendedDocuments: string[],
  keywords?: string[],
];

const clause = ([
  code,
  title,
  summary,
  parentCode,
  category,
  owner,
  auditWeight,
  csrRelevant,
  recommendedDocuments,
  keywords = [],
]: ClauseInput): ClauseNode => ({
  code,
  title,
  summary,
  parentCode,
  category,
  owner,
  auditWeight,
  csrRelevant,
  recommendedDocuments,
  keywords,
  requiresDocument: recommendedDocuments.length > 0,
  level: code.split('.').length,
});

