export const REQUIREMENT_CLAUSES = IATF_CLAUSES.filter((item) => Number(item.code.split('.')[0]) >= 4);

export const LEAF_REQUIREMENT_CLAUSES = REQUIREMENT_CLAUSES.filter(
  (item) => !REQUIREMENT_CLAUSES.some((candidate) => candidate.parentCode === item.code),
);

export const CLAUSE_TOP_LEVEL_FILTERS = REQUIREMENT_CLAUSES.filter(
  (item) => item.parentCode === null || /^[4-9]$|^10$/.test(item.code),
);

export const buildClauseBreadcrumb = (code: string): ClauseNode[] => {
  const lookup = new Map(IATF_CLAUSES.map((item) => [item.code, item]));
  const result: ClauseNode[] = [];
  let current = lookup.get(code);

  while (current) {
    result.unshift(current);
    current = current.parentCode ? lookup.get(current.parentCode) : undefined;
  }

  return result;
};
